+pub(crate) fn get_remote_qabl_info(
+    queryables: &HashMap<u32, (Arc<Resource>, QueryableInfoType)>,
+    res: &Arc<Resource>,
+) -> Option<QueryableInfoType> {
+    queryables
+        .values()
+        .fold(None, |accu, (ref r, ref qabl_info)| {
