+        if ctx.qabl != *new_qabl_info {
+            get_mut_unchecked(ctx).qabl = *new_qabl_info;
+            true
+        } else {
+            false
+        }
+    } else {
+        tracing::warn!(
+            "Request to update QueryableInfo for inexistent face id: {}, on resource: '{}'",
+            face_id,
+            res.expr()
+        );
+        false
+    }
+}

